package com.zidio.keystone.controller; import com.zidio.keystone.dto.*; import com.zidio.keystone.service.AuthService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController{private final AuthService s; public AuthController(AuthService s){this.s=s;} @PostMapping("/login") public LoginResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);} }
